'use client';

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { ChevronDownIcon, ListTodoIcon, XIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { AgentWorkspace } from '../pi-app/agent-workspace';
import type { WorkspaceBarPanel } from '../pi-app/workspace-bar';
import { defaultKinds } from '../pi-app-kinds/pi-app-kinds';
import { ChatTextProvider } from '../pi-chat/labels';
import { chatTextFor } from '../pi-chat/locale';
import { Markdown } from '../pi-chat-markdown/markdown';
import { cn } from '../utils/utils';
import { usePhone } from '../utils/use-media';
import { PmComposer } from './pm-composer';
import { PointComment } from './point-comment';
import { usePmPanel } from './use-pm-panel';
import { POINT_PREFACE, pointMessage } from './point-message';
import { usePmMentions } from './pm-mentions';
import { TaskDetail, TaskRequestCard, taskTokens } from '../task-board/task-board';
import type { TaskRecord } from '@hachej/boring-ui-kit/task-board';
import { selectTasks } from '@hachej/boring-ui-kit/task-board';
import { PmRequestStatus, requestOutcome } from './pm-task-source';
import type { ImproveSpec, StudioTaskBoardSeam } from './use-pm-panel';
import { useImproveAgent } from './use-improve-agent';
import type { ImproveProp } from './use-improve-agent';
import { pmTextFor } from './pm-text';
import type { PmPreset } from './pm-composer';
import type { PmText } from './pm-text';
import { useSiblingPointing } from './point-frames';
import { createPrivacyPolicy } from '@hachej/boring-feedback/page';
import { PM_HOST_ORIGINS, usePmHostTheme } from './pm-host-theme';
import { PointChipView } from './inline-point-input';

export { PM_HOST_ORIGINS } from './pm-host-theme';
export { PmComposer, PointerIcon } from './pm-composer';
export type { PmComposerProps, PmPreset } from './pm-composer';
export { usePmPanel } from './use-pm-panel';
export type { PmComment, PmPanelState } from './use-pm-panel';
export { PointComment } from './point-comment';
export { usePmMentions } from './pm-mentions';
export { pmTextEn, pmTextFor, pmTextFr } from './pm-text';
export type { PmText } from './pm-text';
export { PointChipView } from './inline-point-input';
export { pointMessage } from './point-message';
export type { ImproveSpec, PmVoice, PmTranscript, StudioTaskBoardSeam } from './use-pm-panel';
export { useImproveAgent, isImproveAgent } from './use-improve-agent';
export type { ImproveAgent, ImproveProp } from './use-improve-agent';

interface Binding { readonly spec: ImproveSpec; readonly open: boolean; readonly close: () => void; readonly onFull?: ((full: boolean, collapse: () => void) => void) | undefined }
interface Pending { readonly open: boolean; readonly close: () => void; readonly problem: string | undefined; readonly retry: () => void; readonly text: PmText }
const PmContext = createContext<Binding | Pending | null>(null);
const AppNameContext = createContext('');
const defaultPolicy = createPrivacyPolicy();
async function imageFiles(files: readonly File[]) {
  return Promise.all(files.map(async (file, index) => {
    if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type) || file.size > 3 * 1024 * 1024) throw new Error('Joignez une image de moins de 3 Mo.');
    let binary = '';
    for (const byte of new Uint8Array(await file.arrayBuffer())) binary += String.fromCharCode(byte);
    return { id: `pm-file-${Date.now()}-${index}`, name: file.name, content: { type: 'image' as const, mimeType: file.type, data: btoa(binary) } };
  }));
}

/** One borrowed PM conversation, resolved through the app's existing door on the first open. */
export function PmPanelProvider({ spec, open, close, appName, locale, onFull, children }: { readonly spec?: ImproveProp | undefined; readonly open: boolean; readonly close: () => void; readonly appName?: string | undefined; readonly locale?: string | undefined; readonly onFull?: ((full: boolean, collapse: () => void) => void) | undefined; readonly children: ReactNode }) {
  const resolved = useImproveAgent(spec, open, { ...(appName ? { appName } : {}), ...(locale ? { locale } : {}) });
  const text = pmTextFor(locale);
  const value = useMemo<Binding | Pending | null>(() => resolved.spec ? { spec: resolved.spec, open, close, onFull } : spec ? { open, close, problem: resolved.problem, retry: resolved.retry, text } : null, [resolved.spec, resolved.problem, resolved.retry, spec, open, close, onFull, text]);
  return <PmContext.Provider value={value}><AppNameContext.Provider value={appName ?? ''}>{children}</AppNameContext.Provider></PmContext.Provider>;
}

/** Desktop: beside the pointable app. Phone: full-screen chat, or the in-flow strip while pointing. */
export function ImproveLayout({ children, navigation, screen }: { readonly children: ReactNode; readonly navigation?: ReactNode; readonly screen?: string }) {
  const bound = useContext(PmContext);
  const [page, setPage] = useState<HTMLDivElement | null>(null);
  const binding = bound && 'spec' in bound ? bound : null, pending = bound && !('spec' in bound) ? bound : null;
  const controller = binding?.spec.controller;
  const [instance, setInstance] = useState({ controller, sequence: 0 });
  if (instance.controller !== controller) setInstance({ controller, sequence: instance.sequence + 1 });
  const [pointing, setPointing] = useState(false);
  const [opened, setOpened] = useState(false);
  if (binding?.open && !opened) setOpened(true);
  return <div data-pm-layout="" className="relative flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden md:flex-row">
    <div ref={setPage} data-pm-page="" data-pm-screen={screen} className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">{children}</div>
    {bound && inFrame() && <SiblingPoint page={page} screen={screen ?? ''} bound={bound} />}
    {binding && opened && <PanelSession key={instance.sequence} binding={binding} page={page} screen={screen} report={setPointing} />}
    {pending?.open && <PmConnecting text={pending.text} problem={pending.problem} retry={pending.retry} close={pending.close} className="absolute inset-0 z-40 md:static md:w-[26rem] md:shrink-0" />}
    <div data-pm-navigation="" hidden={Boolean(bound?.open && !pointing)} className="shrink-0 md:hidden">{navigation}</div>
  </div>;
}

const inFrame = () => typeof window !== 'undefined' && window.parent !== window;

/** This page is framed beside a standalone PM: pointing started there runs here, and this frame's own PM steps aside for it. */
function SiblingPoint({ page, screen, bound }: { readonly page: HTMLElement | null; readonly screen: string; readonly bound: Binding | Pending }) {
  const text = 'spec' in bound ? pmTextFor(bound.spec.chatProps?.locale) : bound.text;
  useSiblingPointing({ app: useContext(AppNameContext), page, screen, policy: ('spec' in bound ? bound.spec.policy : undefined) ?? defaultPolicy, text, onStart: bound.close });
  return null;
}

function PanelSession({ binding, page, screen, report }: { readonly binding: Binding; readonly page: HTMLElement | null; readonly screen: string | undefined; readonly report: (pointing: boolean) => void }) {
  const pm = usePmPanel(binding.spec, binding.open, page, screen, { comment: useFinePointer() });
  const strip = pm.state.mode === 'point' || pm.state.mode === 'navigate';
  const returning = useRef(pm.returnToComposer);
  useLayoutEffect(() => { returning.current = pm.returnToComposer; });
  const collapse = useCallback(() => returning.current(), []);
  useLayoutEffect(() => { report(strip); }, [strip, report]);
  const onFull = binding.onFull;
  useEffect(() => { onFull?.(strip, collapse); }, [strip, collapse, onFull]);
  useEffect(() => () => { onFull?.(false, collapse); }, [onFull, collapse]);
  return <section hidden={!binding.open} data-feedback-ignore="" data-testid="pm-panel" data-mode={strip ? pm.state.mode : 'chat'}
    className={cn('min-h-0 min-w-0 bg-background md:static md:w-[26rem] md:shrink-0 md:border-l', binding.open && 'flex flex-col', strip ? 'shrink-0' : 'absolute inset-0 z-40')}>
    <PmWorkspace spec={binding.spec} pm={pm} page={page} preset="touch" open={binding.open} close={binding.close} />
  </section>;
}

const COARSE = '(pointer: coarse)', WIDE = '(min-width: 768px)';
const fine = () => !matchMedia(COARSE).matches && matchMedia(WIDE).matches;
function useFinePointer() {
  return useSyncExternalStore(listener => {
    const queries = [matchMedia(COARSE), matchMedia(WIDE)];
    for (const query of queries) query.addEventListener('change', listener);
    return () => { for (const query of queries) query.removeEventListener('change', listener); };
  }, fine, () => false);
}

function PmConnecting({ text, problem, retry, close, className }: { readonly text: PmText; readonly problem: string | undefined; readonly retry: () => void; readonly close?: (() => void) | undefined; readonly className: string }) {
  return <section data-feedback-ignore="" data-testid="pm-panel" data-mode="connecting" className={cn('flex min-h-0 flex-col gap-3 bg-background p-4', className)}>
    <h2 className="m-0 text-sm">{text.title}</h2>
    <p role={problem ? 'alert' : 'status'} className="m-0 text-sm text-muted-foreground">{problem ? text.connectionFailed : text.connecting}</p>
    {problem && <Button variant="outline" onClick={retry} data-testid="pm-connect-retry">{text.retry}</Button>}
    {close && <Button variant="ghost" data-testid="pm-close" onClick={close}>{text.close}</Button>}
  </section>;
}

export interface PmChatProps {
  /** One line, `{ agent: 'pm' }` (the kit opens the app's PM door), or a host `ImproveSpec`. */
  readonly spec: ImproveProp;
  /** The page this chat points at when it is in the same document. Without it, pointing needs `siblingApp`. */
  readonly page?: HTMLElement | null;
  /** The app's name: this PM sits in a frame beside the app's frame, and pointing runs there. */
  readonly siblingApp?: string;
  readonly screen?: string;
  readonly preset?: PmPreset;
  readonly appName?: string;
  readonly locale?: string;
  readonly close?: () => void;
}

/** The PM, plugged anywhere: the regular chat filling its container. What the PM presents sits beside it when the container is wide enough, otherwise replaces it with Back. */
export function PmChat({ spec, appName, locale, close, ...rest }: PmChatProps) {
  const resolved = useImproveAgent(spec, true, { ...(appName ? { appName } : {}), ...(locale ? { locale } : {}) });
  const controller = resolved.spec?.controller;
  const [instance, setInstance] = useState({ controller, sequence: 0 });
  if (instance.controller !== controller) setInstance({ controller, sequence: instance.sequence + 1 });
  if (!resolved.spec) return <PmConnecting text={pmTextFor(locale)} problem={resolved.problem} retry={resolved.retry} close={close} className="flex-1" />;
  return <PmChatSession key={instance.sequence} spec={resolved.spec} close={close} {...rest} />;
}

function PmChatSession({ spec, page = null, siblingApp, screen, preset = 'desktop', close }: Omit<PmChatProps, 'spec' | 'appName' | 'locale'> & { readonly spec: ImproveSpec }) {
  const pm = usePmPanel(spec, true, page, screen, { comment: preset === 'desktop' && siblingApp === undefined, sibling: siblingApp });
  return <div data-testid="pm-chat" data-mode={pm.state.mode} className="flex min-h-0 min-w-0 flex-1 flex-col"><PmWorkspace spec={spec} page={page} pm={pm} preset={preset} open close={close} beside={siblingApp !== undefined} /></div>;
}

/** `?pm=standalone`: only the PM, full frame, for a host's column beside the app's frame. Same origin and session as the app, no route of its own. */
export function PmStandalone({ spec, appName, locale, hostOrigins = PM_HOST_ORIGINS }: { readonly spec: ImproveProp; readonly appName: string; readonly locale?: string | undefined; readonly hostOrigins?: readonly string[] | undefined }) {
  usePmHostTheme(hostOrigins);
  return <main data-testid="pm-standalone" className="app-shell flex h-dvh min-h-0 flex-col overflow-hidden bg-background text-foreground">
    <PmChat spec={spec} appName={appName} siblingApp={appName} preset="touch" {...(locale ? { locale } : {})} />
  </main>;
}

/** Wiring only: the regular agent page, with the existing point composer and a host Tasks panel. */
function PmWorkspace({ spec, pm, page, preset, open, close, beside = false }: { readonly spec: ImproveSpec; readonly pm: ReturnType<typeof usePmPanel>; readonly page: HTMLElement | null; readonly preset: PmPreset; readonly open: boolean; readonly close?: (() => void) | undefined; readonly beside?: boolean }) {
  const { text } = pm;
  // On a phone the chat gives the page its screen while pointing. A PM beside the app's frame covers nothing.
  const phone = usePhone() && !beside;
  const strip = pm.state.mode === 'point' || pm.state.mode === 'navigate';
  const root = useRef<HTMLDivElement | null>(null);
  const kinds = useMemo(() => spec.artifactKinds ?? defaultKinds({ locale: text.locale }), [spec.artifactKinds, text.locale]);
  const mentions = usePmMentions(spec.tasks, spec.chatProps?.mentions, text);
  const edit = useCallback((value: string) => { spec.controller.setText(value); }, [spec.controller]);
  const refreshTasks = spec.tasks?.refresh;
  useEffect(() => { if (open) refreshTasks?.(); }, [open, refreshTasks]);
  const seenKey = `boring.pm.ships.${JSON.stringify(pm.snapshot.identity)}`;
  const [seen, setSeen] = useState<readonly string[]>(() => { try { const value: unknown = JSON.parse(localStorage.getItem(seenKey) ?? '[]'); return Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : []; } catch { return []; } });
  const ships = spec.tasks ? selectTasks(spec.tasks.tasks, { filter: 'mine', currentUser: spec.tasks.currentUser }).filter(task => !task.technical && requestOutcome(task) === 'live').map(task => `${task.id}:${task.updated_at ?? ''}`) : [];
  const tasksLabel = text.locale === 'fr' ? 'Tâches' : 'Tasks';
  const barPanels: readonly WorkspaceBarPanel[] = [{ id: 'tasks', label: tasksLabel, icon: ListTodoIcon, dot: spec.tasks?.unread ?? ships.some(ship => !seen.includes(ship)), onOpenChange: spec.tasks?.onOpenChange, onOpen: () => {
    refreshTasks?.(); setSeen(ships); try { localStorage.setItem(seenKey, JSON.stringify(ships)); } catch { /* viewer storage is optional */ }
  }, content: () => <div data-testid="pm-task-board-seam" className="min-h-0 flex-1 overflow-auto">{spec.tasks ? <>{spec.tasks.header}<PmRequests seam={spec.tasks} text={text} /></> : <p role="status" className="p-4 text-sm text-muted-foreground">{text.connectionFailed}</p>}</div> }];
  useEffect(() => {
    if (!pm.focusVersion || !open || strip) return;
    const input = root.current?.querySelector<HTMLElement>('[data-testid=composer-input]');
    input?.focus({ preventScroll: true });
    if (input instanceof HTMLTextAreaElement) input.setSelectionRange(input.value.length, input.value.length);
  }, [pm.focusVersion, open, strip, spec.controller]);
  const pointProps = { preset, text, selections: pm.state.chips, onRemove: pm.remove, show: pm.state.show, onShow: (value: boolean) => pm.dispatch({ type: 'show', value }),
    canPoint: pm.canPoint, onPoint: () => pm.dispatch({ type: 'point' }), onReturn: pm.returnToComposer, onOpenRecorder: () => pm.dispatch({ type: 'return' }), focusInput: pm.focusVersion > 0 && open && !strip, voice: pm.voice, meta: pm.meta, notice: pm.sent ? text.sentToPm : undefined };
  const uncertain = pm.snapshot.send.kind === 'unknown' ? pm.snapshot.send.attempt : undefined;
  const transcript = pm.voice.phase === 'processing' ? <p data-testid="pm-transcribing" role="status" className="m-0 px-2">{text.locale === 'fr' ? 'Transcription…' : 'Transcribing…'}</p> : pm.liveText && <p role="status" data-testid="pm-live-transcript" className="m-0 px-2">{pm.liveText}</p>;
  return <ChatTextProvider value={chatTextFor(text.locale)}><div ref={root} className="flex min-h-0 flex-1 flex-col">
    <p role="status" aria-live="polite" data-testid="pm-announce" className="sr-only">{pm.announcement}</p>
    {pm.problem && <p role="alert" className="m-0 px-4 text-sm">{pm.problem}</p>}
    <div hidden={strip && phone} className={cn('min-h-0 flex-1 flex-col', strip && phone ? 'hidden' : 'flex')}>
      <AgentWorkspace layout="embedded" title={spec.appName ?? spec.label ?? text.title} locale={text.locale} controller={spec.controller}
        conversationId={spec.conversationId ?? pm.snapshot.conversationId} conversations={spec.conversations ?? spec.chatProps?.conversations}
        resources={spec.resources} artifactKinds={kinds} autoOpen={Boolean(spec.resources)} barPanels={barPanels} barOptions={{ panelsFirst: true }}
        controls={close && <Button variant="ghost" size="icon" data-testid="pm-close" aria-label={text.close} title={text.close} onClick={close}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>}
        chat={{ ...spec.chatProps, ...(mentions ? { mentions } : {}),
          labels: { ...spec.chatProps?.labels, placeholder: `${text.placeholderBefore}↖${text.placeholderAfter}`, add: text.attach, send: text.send },
          onFiles: spec.chatProps?.onFiles ?? imageFiles, sendContext: pm.sendContext, replyError: spec.chatProps?.replyError ?? (() => text.failed),
          renderEntry: entry => pointMessage(entry, mentions, { preset, text }) ?? spec.chatProps?.renderEntry?.(entry),
          replyFooter: reply => { const entry = pm.snapshot.view?.entries.find(entry => String(entry.id) === reply.entryId); return <>{spec.chatProps?.replyFooter?.(reply)}{entry && spec.tasks?.renderRequest?.({ entry, edit })}</>; },
          renderComposer: composer => strip ? <>{beside && pm.state.chips.length > 0 && <div data-testid="pm-beside-chips" className="flex flex-wrap gap-1.5 pb-2">{pm.state.chips.map(chip => <PointChipView key={chip.id} chip={chip} preset={preset} labels={text} onRemove={() => pm.remove(chip.id)} />)}</div>}<PmComposer variant="strip" {...pointProps} /></> : <PmComposer {...pointProps} composer={pm.answerComposer({ ...composer, sendBlocked: composer.sendBlocked || pm.voice.phase === 'processing', ...(uncertain ? { text: uncertain.draft.text.split(POINT_PREFACE)[0]!.trimEnd(), disabled: true } : {}) })} transcript={transcript} /> }} />
    </div>
    {strip && phone && <PmComposer variant="strip" {...pointProps} />}
    {pm.comment && page && <PointComment comment={pm.comment} frame={page} text={text} />}
  </div></ChatTextProvider>;
}

function PmRequests({ seam, text }: { readonly seam: StudioTaskBoardSeam; readonly text: PmText }) {
  const [expanded, setExpanded] = useState(false);
  const [technical, setTechnical] = useState(false);
  const [selected, setSelected] = useState<string>();
  const tasks = selectTasks(seam.tasks, { filter: 'mine', currentUser: seam.currentUser });
  const visible = tasks.filter(task => !task.technical);
  const open = visible.filter(task => requestOutcome(task) === undefined).sort((a, b) => Number(b.waiting_on_you === true) - Number(a.waiting_on_you === true));
  const finished = visible.filter(task => requestOutcome(task) !== undefined);
  const internal = tasks.filter(task => task.technical);
  const detail = tasks.find(task => task.id === selected);
  const openTask = (task: TaskRecord) => { setSelected(task.id); seam.onOpen(task); };
  const label = { live: text.outcomeLive, withdrawn: text.outcomeWithdrawn, closed: text.outcomeClosed } as const;
  const card = (task: TaskRecord) => {
    const outcome = requestOutcome(task);
    return <TaskRequestCard key={task.id} task={task} variant="compact" locale={text.locale} href="#" onOpen={openTask}
      actions={outcome ? undefined : seam.cardActions?.(task)} pill={outcome
        ? <span className={cn('contents', taskTokens.pill)}><Badge variant={outcome === 'live' ? 'secondary' : 'outline'} data-task-outcome={outcome}>{label[outcome]}</Badge></span>
        : <PmRequestStatus task={task} text={text} />} />;
  };
  if (detail) return <div className="flex flex-col gap-4 p-4">
    <Button variant="ghost" data-testid="pm-request-back" className="self-start" onClick={() => setSelected(undefined)}>{text.back}</Button>
    <TaskDetail task={detail} actions={requestOutcome(detail) ? undefined : seam.cardActions?.(detail)} />
    {detail.spec && <Markdown text={detail.spec} />}
    {detail.history?.map((item, index) => <p key={item.id ?? index} className="m-0 text-sm">{item.note}</p>)}
  </div>;
  return <div className="flex flex-col gap-4 p-4">
    <section data-boring="task-board" className="flex flex-col gap-3" aria-label={text.requests}>
      <h3 className="m-0 text-sm font-semibold">{text.requests}</h3>
      {([true, false] as const).map(waiting => {
        const group = open.filter(task => (task.waiting_on_you === true) === waiting);
        return group.length > 0 && <section key={String(waiting)} className="flex flex-col gap-2" aria-label={waiting ? text.awaiting : text.inProgress}>
          <h4 className="m-0 text-xs text-muted-foreground">{waiting ? text.awaiting : text.inProgress}</h4>
          {group.map(card)}
        </section>;
      })}
    </section>
    {finished.length > 0 && <section data-testid="pm-finished" aria-label={text.finished(finished.length)} className="flex flex-col gap-2">
      <Button variant="ghost" data-testid="pm-finished-toggle" aria-expanded={expanded} aria-controls="pm-finished-list" onClick={() => setExpanded(!expanded)}
        className="min-h-11 justify-between px-1 text-sm font-semibold text-muted-foreground">
        {text.finished(finished.length)}<ChevronDownIcon aria-hidden="true" className={cn('size-4 transition-transform', expanded && 'rotate-180')} />
      </Button>
      {expanded && <div id="pm-finished-list" role="list" aria-label={text.finished(finished.length)} className="flex flex-col gap-2">{finished.map(card)}</div>}
    </section>}
    {internal.length > 0 && <section className="flex flex-col gap-2">
      <Button variant="ghost" data-testid="pm-technical-toggle" aria-expanded={technical} onClick={() => setTechnical(!technical)} className="min-h-11 justify-between">{text.technical} ({internal.length})<ChevronDownIcon aria-hidden="true" /></Button>
      {technical && <div role="list" className="flex flex-col gap-2">{internal.map(card)}</div>}
    </section>}
  </div>;
}

'use client';

import { useLayoutEffect, useRef, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';
import { CheckIcon, HandIcon, MicIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group';
import { Composer } from '../pi-chat/composer';
import type { ComposerProps } from '../pi-chat/composer';
import type { VoiceMessageHandle } from '../pi-chat/config';
import { RecordingBar } from '../pi-chat-voice/voice-message';
import { cn } from '../utils/utils';
import { InlinePointInput } from './inline-point-input';
import type { PointChip } from './point-state';
import { clock, pmTextFr } from './pm-text';
import type { PmText } from './pm-text';

/** `touch`: the app's sheet and strip (C2–C7). `desktop`: Studio's conversation column (D1, D7–D9). Same behaviour and strings. */
export type PmPreset = 'touch' | 'desktop';

/** One composer for a sheet, a conversation column or an ambient bar. The host owns placement, admission and capture. */
export interface PmComposerProps {
  readonly variant?: 'composer' | 'strip';
  readonly preset?: PmPreset;
  readonly text?: PmText;
  readonly composer?: ComposerProps;
  readonly selections?: readonly PointChip[];
  readonly onRemove?: (id: string) => void;
  /** Strip only: `true` a tap selects (`select`), `false` it goes through to the app (`navigate`). */
  readonly show: boolean;
  readonly onShow: (show: boolean) => void;
  /** Compose only: « Montrer » enters the strip without recording. */
  readonly onPoint?: () => void;
  /** Compose only: `false` while there is no page to point at (a standalone PM with no app frame beside it). */
  readonly canPoint?: boolean;
  readonly onReturn?: () => void;
  readonly onOpenRecorder?: () => void;
  readonly focusInput?: boolean;
  readonly voice?: VoiceMessageHandle;
  readonly transcript?: ReactNode;
  /** « Dicté · 0:14 · 2 captures · modifiable » under the draft; absent when there is nothing to say. */
  readonly meta?: string | undefined;
  /** Strip only: « Envoyé au PM » in place of the idle hint for a moment after a comment went straight to the PM (spec 1 §3b). */
  readonly notice?: string | undefined;
}
const noSelections: readonly PointChip[] = [];

/** The kit pointer arrow (spec README rule 5), drawn as lucide draws its icons. */
export function PointerIcon({ className, style }: { readonly className?: string; readonly style?: CSSProperties }) {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className={className} style={style}><path d="M3 3l7 17 2.5-7.5L20 10z" /></svg>;
}

// Shapes are theme tokens: `--radius` drives the host shadcn controls' own radius inside a scope.
const round = { '--radius': 'var(--pm-radius-round)' } as CSSProperties;
const segment = { '--radius': 'var(--pm-radius-segment)' } as CSSProperties;
/** Inside the dark strip the host controls read the inverted roles: outline circles on `primary`, a light « ✓ Terminer » pill. */
const stripScope = { '--background': 'var(--primary)', '--foreground': 'var(--primary-foreground)', '--border': 'var(--pm-strip-line)', '--secondary': 'var(--primary-foreground)', '--secondary-foreground': 'var(--primary)', '--muted': 'var(--primary-foreground)' } as CSSProperties;
const micScope = { ...round, '--primary': 'var(--pm-mic)', '--primary-foreground': 'var(--pm-mic-foreground)' } as CSSProperties;

export function PmComposer(props: PmComposerProps) {
  return props.variant === 'strip' ? <Strip {...props} /> : <Compose {...props} />;
}

/**
 * C4's hint on the touch strip: right-aligned, at most two lines. The « ✓ Terminer » pill never shrinks, so when the whole hint would take a
 * third line it shortens to « Parlez et touchez » (spec 1 §2). A wider strip brings the whole hint back.
 */
function RecHint({ text, touch }: { readonly text: PmText; readonly touch: boolean }) {
  const hint = useRef<HTMLSpanElement | null>(null);
  const [short, setShort] = useState(false);
  useLayoutEffect(() => {
    const node = hint.current, group = node?.parentElement;
    if (!touch || !node || !group) return;
    const tooTall = () => node.offsetHeight > 2 * parseFloat(getComputedStyle(node).lineHeight) + 1;
    if (!short && tooTall()) { setShort(true); return; }
    if (typeof ResizeObserver === 'undefined') return;
    let width = group.clientWidth;
    const observer = new ResizeObserver(() => {
      const next = group.clientWidth;
      if (short ? next > width : tooTall()) setShort(!short);
      width = next;
    });
    observer.observe(group);
    return () => observer.disconnect();
  }, [touch, short, text]);
  return <span ref={hint} data-testid="pm-hint" data-short={short ? '' : undefined} className={cn('min-w-0 text-right text-xs', touch ? 'leading-[1.25] text-primary-foreground/85' : 'text-primary-foreground/80')}>
    {short ? text.hintRecShort : text.hintRec}</span>;
}

/** Spec 1 §1–2 (Julien 2026-10-28): no pause in the strip (the timer opens the recorder for that) and a labelled « ✓ Terminer » pill, never a bare ×. */
function Strip({ preset = 'touch', text = pmTextFr, show, onShow, onReturn, onOpenRecorder, voice, notice }: PmComposerProps) {
  const touch = preset === 'touch';
  const recording = voice?.phase === 'starting' || voice?.phase === 'recording';
  const circle = touch ? 'min-h-11 min-w-11' : 'min-h-[34px] min-w-[34px]';
  return <div data-feedback-ignore="" data-pm-strip="" data-testid="pm-strip" data-preset={preset} data-phase={recording ? 'rec' : 'idle'} data-pointing={show}
    className={cn('flex shrink-0 items-center gap-2 bg-primary text-primary-foreground', touch ? 'h-15 pr-2 pl-3.5' : 'rounded-pm-box px-3 py-2.5')}
    style={touch ? stripScope : { ...stripScope, '--border': 'var(--primary-foreground)' } as CSSProperties}>
    {recording && <div data-dense="" className="flex shrink-0 rounded-pm-toggle p-0.5 ring-1 ring-inset ring-pm-strip-line [&_[data-pressed]]:text-primary">
      <ToggleGroup value={[show ? 'select' : 'navigate']} onValueChange={values => { if (values[0]) onShow(values[0] === 'select'); }} role="radiogroup" aria-label={text.mode} spacing={0.5}>
        <ToggleGroupItem value="select" role="radio" aria-checked={show} aria-label={text.select} title={text.select} data-testid="pm-select" style={segment}
          className={touch ? 'min-h-[38px] min-w-[38px]' : 'min-h-7 min-w-8'}><PointerIcon className={touch ? 'size-4' : 'size-3.5'} /></ToggleGroupItem>
        <ToggleGroupItem value="navigate" role="radio" aria-checked={!show} aria-label={text.navigate} title={text.navigate} data-testid="pm-navigate" style={segment}
          className={touch ? 'min-h-[38px] min-w-[38px]' : 'min-h-7 min-w-8'}><HandIcon className={touch ? 'size-4' : 'size-3.5'} aria-hidden="true" /></ToggleGroupItem>
      </ToggleGroup>
    </div>}
    {!recording ? <span data-testid="pm-hint" className={cn('min-w-0 flex-1 text-left', touch ? 'text-[14px] leading-[1.3] text-primary-foreground/90' : 'text-xs text-primary-foreground/80')} data-notice={notice ? '' : undefined} role={notice ? 'status' : undefined}>{notice ?? text.hintIdle}</span>
      // C4: hint, dot and time share one right-aligned group (gap 6), so the hint keeps at most two lines at 390px.
      : <span className="flex min-w-0 flex-1 items-center justify-end gap-1.5">
        {show && <RecHint text={text} touch={touch} />}
        {/* The host button's transparent 1px border is taken back by the margins: the visible gap to the hint stays 5–6px. */}
        <span className={touch ? 'flex shrink-0 -mr-px -ml-0.5 [&_button]:px-0' : 'flex shrink-0 [&_button]:px-2.5'}><Button variant={touch ? 'ghost' : 'outline'} size={touch ? 'default' : 'sm'} data-testid="pm-timer" aria-label={text.recorder} title={text.recorder} onClick={onOpenRecorder}
          className={cn('shrink-0 gap-1.5 tabular-nums', touch ? 'min-h-11' : 'min-h-[26px]')} style={touch ? undefined : round}>
          {/* Grey while the recorder holds the recording paused: the strip itself has no pause. */}
          <span aria-hidden="true" className={cn('shrink-0 rounded-pm-round', voice?.paused ? 'bg-primary-foreground/50' : 'bg-destructive', touch ? 'size-2.5' : 'size-2')} />
          <span className={cn('font-normal', touch ? 'text-[14px]' : 'text-[13px]')}>{clock(voice?.seconds ?? 0)}</span></Button></span>
      </span>}
    {!recording && <Button variant={touch ? 'outline' : 'default'} size="icon" data-testid="pm-mic" aria-label={text.speak} title={text.speak} disabled={!voice?.canStart}
      onClick={() => voice?.start()} className={cn('shrink-0', circle)} style={touch ? round : micScope}>
      <MicIcon className={touch ? 'size-[18px]' : 'size-[15px]'} aria-hidden="true" /></Button>}
    <span className={cn('flex shrink-0 [&_button]:font-semibold', touch ? '[&_button]:h-11 [&_button]:gap-1.5 [&_button]:px-3.5 [&_button]:text-[14px]' : '[&_button]:h-[34px] [&_button]:gap-1.5 [&_button]:px-3 [&_button]:text-[13px]')}>
      <Button variant="secondary" data-testid="pm-done" aria-label={text.doneLabel} title={text.doneLabel} onClick={onReturn} className="shrink-0" style={round}>
        <CheckIcon className={touch ? 'size-4' : 'size-3.5'} strokeWidth={2.5} aria-hidden="true" /><span>{text.done}</span></Button></span>
  </div>;
}

function Compose({ preset = 'touch', text = pmTextFr, composer, selections = noSelections, onRemove, show, onPoint, canPoint = true, onShow, focusInput, voice, transcript, meta }: PmComposerProps) {
  if (!composer) throw new Error('PmComposer needs composer props outside strip mode');
  const touch = preset === 'touch';
  const recording = voice?.phase === 'starting' || voice?.phase === 'recording';
  const point = () => { if (onPoint) onPoint(); else onShow(!show); };
  const montrer = <Button variant="ghost" size="icon" disabled={composer.disabled || composer.sendBlocked || !canPoint} aria-pressed={false} onClick={point} data-testid="pm-show" aria-label={text.show} title={canPoint ? text.showTitle : text.showUnavailable}
    className={touch ? 'min-h-10 min-w-10' : 'min-h-[34px] min-w-[34px]'}><PointerIcon className={touch ? 'size-4' : 'size-[15px]'} /></Button>;
  const mic = voice && !recording && <Button variant={touch ? 'ghost' : 'default'} size="icon" data-testid="pm-mic" aria-label={text.dictate} title={text.dictate} onClick={voice.start}
    disabled={composer.disabled || !voice.canStart || voice.phase !== 'idle'} className={touch ? 'min-h-10 min-w-10' : 'min-h-9 min-w-9'} style={touch ? undefined : micScope}>
    <MicIcon className={touch ? 'size-[18px]' : 'size-[15px]'} aria-hidden="true" /></Button>;
  const selected = new Set(selections.map(chip => chip.id));
  const placeholder = <>{text.placeholderBefore}<PointerIcon className={cn('inline text-muted-foreground', touch ? 'size-4' : 'size-3.5')} style={{ verticalAlign: '-3px' }} />{text.placeholderAfter}</>;
  const filled = Boolean(composer.text.trim()) || selections.length > 0;
  return <div data-feedback-ignore="" data-testid="pm-composer" data-preset={preset} data-filled={filled || undefined}
    className={cn('flex min-w-0 flex-col gap-2',
      // The box: the host InputGroup with the panel's radius; its controls keep the control radius.
      '[--radius:var(--pm-radius-box)] [&_[data-testid=composer-controls]]:[--radius:var(--pm-radius-control)] [&_[data-slot=input-group]]:!bg-background [&_[data-slot=input-group]]:!opacity-100 [&_[data-slot=composer-field]]:min-h-0',
      // The host addon mutes its text; the composer's controls are full ink (C2).
      '[&_[data-testid=composer-controls]]:text-foreground',
      '[&_[data-testid=composer-submit]]:text-primary-foreground [&_[data-testid=composer-submit]:disabled]:bg-pm-send-idle [&_[data-testid=composer-submit]:disabled]:opacity-100',
      '[&_[data-slot=input-group-control]]:placeholder:text-pm-hint [&_[data-slot=composer-placeholder]]:text-pm-hint',
      // D9: the highlighted task row takes the full muted fill.
      '[&_[data-testid=mention-item][aria-selected=true]]:bg-muted',
      // D9: the typed `@d-2` as an inline token (padding 1 6 without moving the text: the margin takes it back).
      '[&_[data-slot=composer-mention-query]]:rounded-pm-token [&_[data-slot=composer-mention-query]]:bg-muted [&_[data-slot=composer-mention-query]]:-mx-1.5 [&_[data-slot=composer-mention-query]]:px-1.5 [&_[data-slot=composer-mention-query]]:py-px',
      touch ? '[&_[data-testid=composer-controls]]:gap-2 [&_[data-testid=composer-controls]_button]:min-h-10 [&_[data-testid=composer-controls]_button]:min-w-10 [&_[data-testid=composer-input]]:text-[15px] [&_[data-slot=composer-placeholder]]:text-[15px]'
        : '[&_[data-testid=composer-controls]]:gap-2 [&_[data-testid=composer-input]]:text-sm [&_[data-slot=composer-placeholder]]:text-sm [&_[data-testid=composer-submit]]:min-h-9 [&_[data-testid=composer-submit]]:min-w-9 [&_[data-testid=composer-plus]]:min-h-[34px] [&_[data-testid=composer-plus]]:min-w-[34px] [&_[data-testid=composer-plus]]:[--radius:var(--pm-radius-round)] [&_[data-testid=composer-plus]]:ring-1 [&_[data-testid=composer-plus]]:ring-inset [&_[data-testid=composer-plus]]:ring-border',
      // D8/D9: focused or filled, the box outline turns primary, without the host focus ring.
      !touch && 'data-[filled]:[&_[data-slot=input-group]]:border-primary [&_[data-slot=input-group]]:has-[:focus-visible]:border-primary [&_[data-slot=input-group]]:!ring-0')}>
    {transcript}
    <Composer {...composer} attachments={composer.attachments.filter(image => !selected.has(image.id))}
      placeholderContent={placeholder}
      renderInput={selections.length || meta ? ({ text: value, onText, onCaret, onSend }) => <InlinePointInput text={value} preset={preset} labels={text} selections={selections} onText={onText} onCaret={onCaret}
        onRemove={id => onRemove?.(id)} onSend={onSend} disabled={composer.disabled} focus={focusInput} placeholder={placeholder} meta={meta} /> : composer.renderInput}
      markMentionQuery chips={<>{montrer}{composer.chips}</>}
      recording={recording && voice ? <div className="flex w-full min-w-0 items-center gap-1">{montrer}<RecordingBar voice={voice} testId="pm-voice-send" /></div> : composer.recording}
      barEnd={<>{composer.barEnd}{mic}</>} />
  </div>;
}

